from h import *
O=[]
O.append(R(6588001,
("Bol burrito de pavo y frijoles","Este bol burrito de pavo y frijoles ofrece un equilibrio de proteína, fibra e ingredientes frescos, por lo que es una comida saludable y deliciosa. Al preparar un bol burrito se eliminan los carbohidratos de la tortilla del burrito.","4","1 bol",
["1 cucharada de aceite de oliva","1 libra de carne molida de pavo (extra magra)","1 cucharadita de chile en polvo","1/2 cucharadita de semillas de comino","1/2 cucharadita de pimentón","1/8 de cucharadita de sal kosher","1/4 de cucharadita de pimienta negra","1 pimiento rojo mediano (en rodajas)","1 cebolla mediana (en rodajas)","1 taza de tomates roma (en cubos)","1 taza de arroz integral (cocido)","1 taza de frijoles negros (bajos en sodio, escurridos y enjuagados)","2 tazas de lechuga mantequilla (en tiras)","1/8 de taza de queso mezcla mexicana reducido en grasa (rallado)","1/2 taza de cilantro fresco (picado)","1 limón verde entero (cortado en gajos para servir)"],
["En una sartén grande, caliente el aceite de oliva a fuego medio y cocine el pavo molido hasta que se dore, deshaciéndolo con una cuchara mientras se cocina.","Agregue a la sartén el chile en polvo, el comino, el pimentón, la sal kosher y la pimienta negra y cocine 3 minutos para tostar las especias.","Agregue el pimiento y las cebollas y cocine hasta que se ablanden. Agregue los tomates en cubos y revuelva bien para mezclar.","Cocine la mezcla a fuego lento durante unos 10 minutos, para que se integren los sabores y los ingredientes se calienten por completo.","En otra sartén, caliente juntos el arroz y los frijoles negros.","Para armar cada bol, coloque en capas 1/4 de taza de arroz integral, 1/4 de taza de frijoles negros, 1/2 taza de lechuga y aproximadamente 1/2 taza de la mezcla de pavo molido.","Cubra cada bol con aproximadamente 1 cucharada del queso mezcla mexicana rallado y con cilantro picado. Sirva con gajos de limón verde al lado."],[],[]),
("وعاء بوريتو الديك الرومي والفاصولياء","يقدّم وعاء البوريتو هذا بالديك الرومي والفاصولياء توازنًا بين البروتين والألياف والمكوّنات الطازجة، ما يجعله وجبة صحية ولذيذة. وإعداد وعاء بوريتو يستغني عن كربوهيدرات رغيف التورتيلا.","4","1 وعاء",
["1 ملعقة كبيرة زيت زيتون","1 رطل لحم ديك رومي مفروم (قليل الدسم جدًا)","1 ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","½ ملعقة صغيرة بذور كمون","½ ملعقة صغيرة بابريكا","⅛ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود","1 حبة فلفل رومي أحمر متوسطة (مقطّعة شرائح)","1 حبة بصل متوسطة (مقطّعة شرائح)","1 كوب طماطم روما (مقطّعة مكعبات)","1 كوب أرز بني (مطبوخ)","1 كوب فاصولياء سوداء (قليلة الصوديوم، مصفّاة ومشطوفة)","2 كوب خس زبدة (مقطّع شرائح رفيعة)","⅛ كوب جبن مكسيكي مشكّل مخفّض الدسم (مبشور)","½ كوب كزبرة خضراء طازجة (مفرومة)","1 حبة ليمون أخضر كاملة (مقطّعة إلى أرباع للتقديم)"],
["في مقلاة كبيرة، سخّن زيت الزيتون على نار متوسطة واطبخ لحم الديك الرومي المفروم حتى يتحمّر، مع تفتيته بالملعقة أثناء الطهي.","أضف مسحوق الفلفل الحار والكمون والبابريكا وملح الكوشر والفلفل الأسود إلى المقلاة واطبخ 3 دقائق لتحميص التوابل.","أضف الفلفل الرومي والبصل واطبخ حتى يلينا. أضف الطماطم المقطّعة مكعبات وقلّب جيدًا لتمتزج.","اترك الخليط على نار هادئة نحو 10 دقائق لتمتزج النكهات وتسخن المكوّنات جيدًا.","في مقلاة منفصلة، سخّن الأرز والفاصولياء السوداء معًا.","لتجميع كل وعاء، ضع في طبقات ¼ كوب أرز بني و¼ كوب فاصولياء سوداء و½ كوب خس ونحو ½ كوب من خليط لحم الديك الرومي المفروم.","غطِّ كل وعاء بنحو ملعقة كبيرة واحدة من الجبن المكسيكي المشكّل المبشور والكزبرة الخضراء المفرومة. قدّمه مع أرباع الليمون الأخضر إلى جانبه."],[],[])))
O.append(R(6588051,ar=(
"تاكو السمك",
"من قال إن الطعام المكسيكي لا يمكن أن يكون صحيًا؟ تثبت هذه الوصفة أنه يمكن أن يكون صحيًا ولذيذًا! أبهر ضيوفك بهذا الطبق السريع والسهل. يمكنك استخدام أي سمك أبيض متماسك لهذه الوصفة، أو حتى توفو شديد التماسك كخيار نباتي.",
"8","1 تاكو",
["½ كوب صلصة سالسا أو بيكو دي غايو","1 حبة ليمون أخضر صغيرة (عصير)","1 ملعقة كبيرة كزبرة خضراء طازجة (مفرومة)","1 ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","1 بخّة (0.25 غ) بخاخ طهي غير لاصق","1¼ رطل سمك أبيض متماسك، مثل البلطي أو الهلبوت","½ كوب زبادي يوناني سادة خالٍ من الدسم","1 ملعقة كبيرة صلصة حارة","8 أرغفة تورتيلا ذرة صغيرة بقطر 6 بوصات (مدفّأة)"],
["في وعاء متوسط، اخفق السالسا وعصير الليمون الأخضر والكزبرة الخضراء ومسحوق الفلفل الحار والملح والفلفل. ضعه جانبًا.","ادهن مقلاة قلي كبيرة ببخاخ الطهي. قلّب السمك على نار متوسطة دقيقتين لكل جانب. اسكب خليط السالسا فوق السمك وقلّبه 3 دقائق إضافية.","أخرج السمك من المقلاة وفتّته بالشوكة مع خلطه بخليط السالسا.","في وعاء صغير، اخلط الزبادي والصلصة الحارة. وزّع السمك بالتساوي على 8 أرغفة تورتيلا وضع فوق كل واحدة ملعقة من صلصة الزبادي."],[],[])))
O.append(R(6588125,ar=(
"دجاج كاتشياتوري في القدر البطيء",
"هذه وصفة سهلة لدجاج الكاتشياتوري الكلاسيكي. إنها مثالية للطاهي المستعجل الباحث عن خيار لذيذ واقتصادي.",
"6","1 فخذ دجاج + 1 كوب صلصة",
["1 حبة بصل (مقطّعة شرائح)","1 حبة فلفل رومي كاملة (منزوعة البذور ومقطّعة شرائح)","6 أونصات معجون طماطم (6 أونصات، بدون ملح مضاف)","14½ أونصة طماطم (14.5 أونصة، مقطّعة مكعبات)","3 فص ثوم (مفروم)","1 ملعقة كبيرة بهارات إيطالية","أفخاذ دجاج متوسطة الحجم (منزوعة الجلد)"],
["ضع جميع المكوّنات في القدر البطيء.","اطبخها على درجة الحرارة العالية لمدة 4 ساعات.","قدّم الدجاج فوق معكرونة روتيني من القمح الكامل إن رغبت."],[],[])))
O.append(R(6589479,ar=(
"خبز الصودا الأيرلندي بالقمح الكامل",
"خبز الصودا الأيرلندي بالقمح الكامل هذا مشبع وبسيط بنكهة جوزية خفيفة. يُحضَّر بسرعة دون خميرة، فهو خيار رائع عندما ترغب في خبز منزلي طازج لتتناوله مع الوجبات أو كوجبة خفيفة.",
"24","1 شريحة",
["2 كوب دقيق القمح الكامل","1 كوب دقيق متعدد الاستخدامات","½ كوب زبيب ذهبي","1½ ملعقة صغيرة بيكربونات الصودا","½ ملعقة صغيرة ملح","2 كوب لبن رائب (بتيرميلك) قليل الدسم (قليل الدسم)"],
["سخّن الفرن مسبقًا على 400 درجة فهرنهايت (200 درجة مئوية) وبطّن صينية خَبز بورق الزبدة.","في وعاء خلط كبير، اخلط دقيق القمح الكامل والدقيق متعدد الاستخدامات وبيكربونات الصودا والملح والزبيب.","اصنع حفرة في وسط المكوّنات الجافة وصبّ اللبن الرائب فيها دفعة واحدة. اطوِ المكوّنات بملعقة مطاطية حتى تمتزج فقط. لا تفرط في الخلط.","اقلب العجين على ورق الزبدة وشكّله على هيئة رغيف مستدير. اصنع شقًّا على شكل X في أعلى العجين بسكين حادة بعمق نحو ½ بوصة.","ضعه على الرف الأوسط واخبزه 30 دقيقة أو حتى يتماسك ويصبح بنيًّا ذهبيًا."],[],[])))
